import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.split("\n")

    def score_line(line: str) -> int:
        if not line.strip():
            return -10
        return line.count(",") + line.count('"')

    start_idx = 0
    best_idx = 0
    best_score = -10**9
    for i, line in enumerate(lines[: min(len(lines), 50)]):
        s = score_line(line)
        if s > best_score:
            best_score = s
            best_idx = i
    start_idx = best_idx

    candidate = "\n".join(lines[start_idx:])

    def parse_with_csv(s: str) -> List[List[str]]:
        reader = csv.reader(io.StringIO(s), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        return [row for row in reader]

    rows = parse_with_csv(candidate)

    def is_header(row: List[str]) -> bool:
        if not row:
            return False
        joined = ",".join(row).lower()
        return any(k in joined for k in ["date", "time", "product", "price", "description", "url", "comments"])

    if rows and not is_header(rows[0]):
        for i in range(min(5, len(rows))):
            if is_header(rows[i]):
                rows = rows[i:]
                break

    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    width = len(header)

    cleaned_rows: List[List[str]] = []
    for row in rows[1:]:
        if len(row) == width:
            cleaned_rows.append(row)
        elif len(row) < width:
            cleaned_rows.append(row + [""] * (width - len(row)))
        else:
            merged = row[:width - 1] + [",".join(row[width - 1:])]
            if len(merged) < width:
                merged += [""] * (width - len(merged))
            cleaned_rows.append(merged[:width])

    return {"columns": header, "rows": cleaned_rows}
